package migracion;
import config.ConexionBD;import java.sql.*;import java.math.BigDecimal;import java.util.*;
public final class MigracionNucleoPagosP3 {private MigracionNucleoPagosP3(){}public static void main(String[] a){new MigracionNucleoPagosP3().aplicar();}
 public void aplicar(){try(Connection c=ConexionBD.obtenerConexion()){String db=c.getCatalog();if(db==null||db.isBlank())throw new IllegalStateException("No se pudo identificar la base activa.");Resumen antes=resumen(c);crearTablas(c);agregarColumna(c,db,"pagos","orden_pago_id","BIGINT NULL AFTER reserva_id");agregarColumna(c,db,"pagos","origen_acreditacion","VARCHAR(30) NOT NULL DEFAULT 'ADMINISTRACION' AFTER metodo_pago");agregarColumna(c,db,"pagos","referencia_externa","VARCHAR(150) NULL AFTER referencia");agregarIndice(c,db,"pagos","uk_pagos_orden","UNIQUE KEY uk_pagos_orden (orden_pago_id)");agregarIndice(c,db,"pagos","idx_pagos_origen","KEY idx_pagos_origen (origen_acreditacion, fecha_creacion)");agregarFk(c,db,"pagos","fk_pagos_orden","CONSTRAINT fk_pagos_orden FOREIGN KEY (orden_pago_id) REFERENCES ordenes_pago(id) ON DELETE RESTRICT ON UPDATE CASCADE");Resumen despues=resumen(c);if(!antes.equals(despues))throw new IllegalStateException("La verificación financiera cambió durante la migración.");verificar(c,db);System.out.println("MIGRACION_P3_OK pagos="+despues.cantidad+" acreditado="+despues.acreditado+" pendientes="+despues.pendientes+".");}catch(SQLException e){throw new RuntimeException("No se pudo aplicar la migración P3. Revise conectividad y permisos sin publicar credenciales.",e);}}
 private void crearTablas(Connection c)throws SQLException{ejecutar(c,"CREATE TABLE IF NOT EXISTS ordenes_pago (id BIGINT NOT NULL AUTO_INCREMENT,reserva_id BIGINT NOT NULL,proveedor VARCHAR(30) NOT NULL DEFAULT 'MANUAL',metodo VARCHAR(30) NOT NULL DEFAULT 'TRANSFERENCIA_MANUAL',estado VARCHAR(35) NOT NULL DEFAULT 'CREADA',importe DECIMAL(12,2) NOT NULL,moneda CHAR(3) NOT NULL DEFAULT 'ARS',clave_idempotencia VARCHAR(100) NOT NULL,referencia_externa VARCHAR(150) NULL,url_pago VARCHAR(700) NULL,fecha_expiracion DATETIME NULL,fecha_aprobacion DATETIME NULL,fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uk_ordenes_pago_idempotencia(clave_idempotencia),UNIQUE KEY uk_ordenes_pago_proveedor_referencia(proveedor,referencia_externa),KEY idx_ordenes_pago_reserva(reserva_id,fecha_creacion),KEY idx_ordenes_pago_estado(estado,fecha_actualizacion),CONSTRAINT fk_ordenes_pago_reserva FOREIGN KEY(reserva_id) REFERENCES reservas(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT chk_ordenes_pago_importe CHECK(importe>0),CONSTRAINT chk_ordenes_pago_moneda CHECK(CHAR_LENGTH(moneda)=3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");ejecutar(c,"CREATE TABLE IF NOT EXISTS intentos_pago (id BIGINT NOT NULL AUTO_INCREMENT,orden_pago_id BIGINT NOT NULL,numero_intento INT NOT NULL,estado VARCHAR(35) NOT NULL DEFAULT 'INICIADO',referencia_externa VARCHAR(150) NULL,detalle_error VARCHAR(500) NULL,fecha_inicio DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_fin DATETIME NULL,PRIMARY KEY(id),UNIQUE KEY uk_intentos_pago_orden_numero(orden_pago_id,numero_intento),KEY idx_intentos_pago_estado(estado,fecha_inicio),CONSTRAINT fk_intentos_pago_orden FOREIGN KEY(orden_pago_id) REFERENCES ordenes_pago(id) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT chk_intentos_pago_numero CHECK(numero_intento>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");ejecutar(c,"CREATE TABLE IF NOT EXISTS eventos_pago (id BIGINT NOT NULL AUTO_INCREMENT,orden_pago_id BIGINT NULL,proveedor VARCHAR(30) NOT NULL,evento_externo_id VARCHAR(160) NOT NULL,tipo VARCHAR(80) NOT NULL,estado_procesamiento VARCHAR(25) NOT NULL DEFAULT 'RECIBIDO',firma_valida TINYINT(1) NOT NULL DEFAULT 0,payload_hash CHAR(64) NOT NULL,payload_json JSON NULL,detalle_resultado VARCHAR(500) NULL,fecha_evento DATETIME NULL,fecha_recepcion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_procesamiento DATETIME NULL,PRIMARY KEY(id),UNIQUE KEY uk_eventos_pago_proveedor_evento(proveedor,evento_externo_id),KEY idx_eventos_pago_orden(orden_pago_id,fecha_recepcion),KEY idx_eventos_pago_estado(estado_procesamiento,fecha_recepcion),CONSTRAINT fk_eventos_pago_orden FOREIGN KEY(orden_pago_id) REFERENCES ordenes_pago(id) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");ejecutar(c,"CREATE TABLE IF NOT EXISTS conciliaciones_pago (id BIGINT NOT NULL AUTO_INCREMENT,orden_pago_id BIGINT NOT NULL,estado_local VARCHAR(35) NOT NULL,estado_proveedor VARCHAR(80) NULL,resultado VARCHAR(30) NOT NULL,detalle VARCHAR(500) NULL,fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_conciliaciones_pago_orden(orden_pago_id,fecha),KEY idx_conciliaciones_pago_resultado(resultado,fecha),CONSTRAINT fk_conciliaciones_pago_orden FOREIGN KEY(orden_pago_id) REFERENCES ordenes_pago(id) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");}
 private void agregarColumna(Connection c,String db,String t,String n,String sql)throws SQLException{if(!existe(c,"SELECT 1 FROM information_schema.columns WHERE table_schema=? AND table_name=? AND column_name=?",db,t,n))ejecutar(c,"ALTER TABLE "+t+" ADD COLUMN "+n+" "+sql);}private void agregarIndice(Connection c,String db,String t,String n,String sql)throws SQLException{if(!existe(c,"SELECT 1 FROM information_schema.statistics WHERE table_schema=? AND table_name=? AND index_name=?",db,t,n))ejecutar(c,"ALTER TABLE "+t+" ADD "+sql);}private void agregarFk(Connection c,String db,String t,String n,String sql)throws SQLException{if(!existe(c,"SELECT 1 FROM information_schema.table_constraints WHERE constraint_schema=? AND table_name=? AND constraint_name=?",db,t,n))ejecutar(c,"ALTER TABLE "+t+" ADD "+sql);}private boolean existe(Connection c,String q,String...v)throws SQLException{try(PreparedStatement s=c.prepareStatement(q)){for(int i=0;i<v.length;i++)s.setString(i+1,v[i]);try(ResultSet r=s.executeQuery()){return r.next();}}}private void ejecutar(Connection c,String q)throws SQLException{try(Statement s=c.createStatement()){s.execute(q);}}
 private Resumen resumen(Connection c)throws SQLException{try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) cantidad,COALESCE(SUM(CASE WHEN estado='ACREDITADO' THEN importe ELSE 0 END),0) acreditado,SUM(estado='PENDIENTE') pendientes,SUM(estado='ACREDITADO') acreditados,SUM(estado='ANULADO') anulados,SUM(estado='REEMBOLSADO') reembolsados FROM pagos")){r.next();return new Resumen(r.getLong("cantidad"),r.getBigDecimal("acreditado"),r.getLong("pendientes"),r.getLong("acreditados"),r.getLong("anulados"),r.getLong("reembolsados"));}}private void verificar(Connection c,String db)throws SQLException{for(String t:List.of("ordenes_pago","intentos_pago","eventos_pago","conciliaciones_pago"))if(!existe(c,"SELECT 1 FROM information_schema.tables WHERE table_schema=? AND table_name=?",db,t))throw new IllegalStateException("Falta la tabla "+t);try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM pagos WHERE orden_pago_id IS NOT NULL OR origen_acreditacion<>'ADMINISTRACION' OR referencia_externa IS NOT NULL")){r.next();if(r.getLong(1)!=0)throw new IllegalStateException("Los pagos históricos fueron alterados.");}}private record Resumen(long cantidad,BigDecimal acreditado,long pendientes,long acreditados,long anulados,long reembolsados){}
}
